<?php
declare(strict_types=1);

namespace App\Controllers\Admin;
use App\Core\{AppKernel,Request,Response};
final class AttributesController extends CatalogAdminController
{
    public function index(Request $r):Response{$u=$this->requireUser();if($u instanceof Response)return $u;if(($d=$this->requirePermission($u,'catalog.view'))!==null)return $d;[$q,$a,$o,$s]=$this->filters($r);return $this->adminView('admin/catalog/attributes-index',['title'=>'Atributos','activeNav'=>'catalog','user'=>$u,'page'=>AppKernel::catalog()->attributes($q,$a,25,$o),'attributeOptions'=>AppKernel::catalog()->attributeOptions(),'q'=>$q,'status'=>$s]);}
    public function create(Request $r):Response{$u=$this->requireUser();if($u instanceof Response)return $u;if(($d=$this->requirePermission($u,'attributes.manage'))!==null)return $d;if(($c=$this->requireCsrf($r,$u))!==null)return $c;return $this->run(function()use($r,$u){AppKernel::connection()->transaction(function()use($r,$u){$id=AppKernel::catalog()->createAttribute($r->input('code'),$r->input('name'),$r->input('value_type'),self::nullable($r->input('unit_label')));AppKernel::audit()->record($u->id,'attributes.create','attribute',$id,null,'success');});},'Atributo creado. Permanece inactivo.','/admin/attributes',$u->id,'attributes.create','attribute');}
    public function status(Request $r):Response{$u=$this->requireUser();if($u instanceof Response)return $u;if(($d=$this->requirePermission($u,'attributes.manage'))!==null)return $d;if(($c=$this->requireCsrf($r,$u))!==null)return $c;$id=$r->integer('id');$a=$this->checked($r,'active');return $this->run(function()use($id,$a,$u){AppKernel::connection()->transaction(function()use($id,$a,$u){AppKernel::catalog()->setAttributeActive($id,$a);AppKernel::audit()->record($u->id,$a?'attributes.activate':'attributes.deactivate','attribute',$id,null,'success');});},$a?'Atributo activado.':'Atributo desactivado.','/admin/attributes',$u->id,$a?'attributes.activate':'attributes.deactivate','attribute',$id);}
    public function createOption(Request $r):Response{$u=$this->writer($r);if($u instanceof Response)return $u;$attribute=$r->integer('attribute_id');return $this->run(function()use($r,$u,$attribute){AppKernel::connection()->transaction(function()use($r,$u,$attribute){$id=AppKernel::catalog()->addAttributeOption($attribute,$r->input('value'));AppKernel::audit()->record($u->id,'attributes.option.create','attribute_option',$id,null,'success');});},'Opción creada. Permanece inactiva.','/admin/attributes',$u->id,'attributes.option.create','attribute',$attribute);}
    public function optionStatus(Request $r):Response{$u=$this->writer($r);if($u instanceof Response)return $u;$attribute=$r->integer('attribute_id');$id=$r->integer('id');$active=$this->checked($r,'active');return $this->run(function()use($u,$attribute,$id,$active){AppKernel::connection()->transaction(function()use($u,$attribute,$id,$active){AppKernel::catalog()->setAttributeOptionActive($id,$attribute,$active);AppKernel::audit()->record($u->id,$active?'attributes.option.activate':'attributes.option.deactivate','attribute_option',$id,null,'success');});},$active?'Opción activada.':'Opción desactivada.','/admin/attributes',$u->id,$active?'attributes.option.activate':'attributes.option.deactivate','attribute_option',$id);}
    public function deleteOption(Request $r):Response{$u=$this->writer($r);if($u instanceof Response)return $u;$attribute=$r->integer('attribute_id');$id=$r->integer('id');return $this->run(function()use($u,$attribute,$id){AppKernel::connection()->transaction(function()use($u,$attribute,$id){AppKernel::catalog()->removeAttributeOption($id,$attribute);AppKernel::audit()->record($u->id,'attributes.option.delete','attribute_option',$id,null,'success');});},'Opción eliminada.','/admin/attributes',$u->id,'attributes.option.delete','attribute_option',$id);}
    private function writer(Request $r):object{$u=$this->requireUser();if($u instanceof Response)return $u;if(($d=$this->requirePermission($u,'attributes.manage'))!==null)return $d;if(($c=$this->requireCsrf($r,$u))!==null)return $c;return $u;}
}
